    def test_subagent_response_format_serialized_as_json(self):
        """Test that subagent responseFormat produces JSON-serialized ToolMessage content.

        Verifies the end-to-end flow when `response_format` is set directly on a
        `SubAgent` spec: the subagent's `structured_response` is JSON-serialized
        into the ToolMessage content returned to the parent agent.
        """

        class SubagentFindings(BaseModel):
            findings: str = Field(description="The findings")
            confidence: float = Field(description="Confidence score")
            summary: str = Field(description="Brief summary")

        agent = create_agent(
            model="claude-sonnet-4-20250514",
            system_prompt="You are an orchestrator. Always delegate tasks to the appropriate subagent via the task tool.",
            middleware=[
                SubAgentMiddleware(
                    backend=StateBackend(),
                    subagents=[
                        {
                            "name": "foo",
                            "description": "Call this when the user says 'foo'",
                            "system_prompt": "You are a foo agent",
                            "model": "claude-haiku-4-5",
                            "tools": [],
                            "response_format": ToolStrategy(schema=SubagentFindings),
                        },
                    ],
                )
            ],
        )

        result = agent.invoke(
            {"messages": [HumanMessage(content="foo - tell me how confident you are that pineapple belongs on pizza")]},
            {"recursion_limit": 100},
        )

        agent_messages = [msg for msg in result["messages"] if isinstance(msg, AIMessage)]
        tool_calls = [tc for msg in agent_messages for tc in (msg.tool_calls or [])]
        assert any(tc["name"] == "task" and tc["args"].get("subagent_type") == "foo" for tc in tool_calls)

        task_tool_messages = [msg for msg in result["messages"] if msg.type == "tool" and msg.name == "task"]
        assert len(task_tool_messages) > 0

        task_tool_message = task_tool_messages[0]
        parsed = json.loads(task_tool_message.content)
        assert "findings" in parsed
        assert "confidence" in parsed
        assert "summary" in parsed
        assert isinstance(parsed["findings"], str)
        assert isinstance(parsed["confidence"], (int, float))
        assert isinstance(parsed["summary"], str)

    def test_forked_subagent_reuses_parent_prompt_cache(self):
        """A fork reads the parent prompt prefix from Anthropic's prompt cache."""
        cacheable_context = " ".join("The project identifier is context-cache-test." for _ in range(200))
        agent = create_deep_agent(
            model="anthropic:claude-sonnet-4-6",
            system_prompt=(
                "Delegate the user's request to the forked worker with the task tool. "
                "Do not answer directly.\n\n"
                f"<reference_context>{cacheable_context}</reference_context>"
            ),
            subagents=[
                {
                    "name": "forked-worker",
                    "description": "Completes the delegated task using the inherited context.",
                    "mode": "fork",
                    "tools": [],
                }
            ],
        )

        model_messages: list[tuple[Any, AIMessage]] = []
        for namespace, update in agent.stream(
            {"messages": [HumanMessage(content="Delegate this task: reply with the project identifier.")]},
            subgraphs=True,
            stream_mode="updates",
        ):
            if not isinstance(update, dict):
                continue
            model_update = update.get("model")
            if not isinstance(model_update, dict):
                continue
            messages = model_update.get("messages", [])
            if messages and isinstance(messages[-1], AIMessage):
                model_messages.append((namespace, messages[-1]))

        parent_task_calls = [call for namespace, message in model_messages if not namespace for call in message.tool_calls if call["name"] == "task"]
        assert any(call["args"].get("subagent_type") == "forked-worker" for call in parent_task_calls)

        forked_response = next(message for namespace, message in model_messages if namespace)
        input_details = (forked_response.usage_metadata or {}).get("input_token_details", {})
        cache_read_tokens = input_details.get("cache_read", 0)
        assert isinstance(cache_read_tokens, int)
        assert cache_read_tokens > 0

